/*
 * BMP280 Barometric Altimeter — I2C (raw registers)
 *
 * Wiring:
 *   VCC -> 3.3V (or 5V)
 *   GND -> GND
 *   SCL -> A5
 *   SDA -> A4
 *
 * No external library required — only Wire.h.
 * Reads temperature and pressure, computes altitude.
 * Drag the Temp / hPa sliders on the sensor to simulate
 * different pressure and temperature conditions.
 */

#include <Wire.h>

#define BMP_ADDR 0x76

#define REG_ID        0xD0
#define REG_CTRL_MEAS 0xF4
#define REG_CONFIG    0xF5
#define REG_PRESS_MSB 0xF7
#define REG_TEMP_MSB  0xFA

#define SEA_LEVEL_HPA 1013.25

uint16_t dig_T1;
int16_t  dig_T2, dig_T3;
uint16_t dig_P1;
int16_t  dig_P2, dig_P3, dig_P4, dig_P5;
int16_t  dig_P6, dig_P7, dig_P8, dig_P9;

int32_t t_fine;

uint8_t readReg(uint8_t reg) {
  Wire.beginTransmission(BMP_ADDR);
  Wire.write(reg);
  Wire.endTransmission(false);
  Wire.requestFrom(BMP_ADDR, (uint8_t)1);
  return Wire.read();
}

void readRegs(uint8_t reg, uint8_t *buf, uint8_t len) {
  Wire.beginTransmission(BMP_ADDR);
  Wire.write(reg);
  Wire.endTransmission(false);
  Wire.requestFrom(BMP_ADDR, len);
  for (uint8_t i = 0; i < len; i++) buf[i] = Wire.read();
}

void writeReg(uint8_t reg, uint8_t val) {
  Wire.beginTransmission(BMP_ADDR);
  Wire.write(reg);
  Wire.write(val);
  Wire.endTransmission();
}

void readCalibration() {
  uint8_t buf[26];
  readRegs(0x88, buf, 26);
  dig_T1 = buf[1] << 8 | buf[0];
  dig_T2 = buf[3] << 8 | buf[2];
  dig_T3 = buf[5] << 8 | buf[4];
  dig_P1 = buf[7] << 8 | buf[6];
  dig_P2 = buf[9] << 8 | buf[8];
  dig_P3 = buf[11] << 8 | buf[10];
  dig_P4 = buf[13] << 8 | buf[12];
  dig_P5 = buf[15] << 8 | buf[14];
  dig_P6 = buf[17] << 8 | buf[16];
  dig_P7 = buf[19] << 8 | buf[18];
  dig_P8 = buf[21] << 8 | buf[20];
  dig_P9 = buf[23] << 8 | buf[22];
}

float readTemperature() {
  uint8_t buf[3];
  readRegs(REG_TEMP_MSB, buf, 3);
  int32_t adc_T = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
  int32_t var1 = (((adc_T >> 3) - ((int32_t)dig_T1 << 1)) * ((int32_t)dig_T2)) >> 11;
  int32_t var2 = (((((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
  t_fine = var1 + var2;
  return (t_fine * 5 + 128) >> 8;
}

float readPressure() {
  uint8_t buf[3];
  readRegs(REG_PRESS_MSB, buf, 3);
  int32_t adc_P = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
  int64_t var1 = ((int64_t)t_fine) - 128000;
  int64_t var2 = var1 * var1 * (int64_t)dig_P6;
  var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
  var2 = var2 + (((int64_t)dig_P4) << 35);
  var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
  var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
  if (var1 == 0) return 0;
  int64_t p = 1048576 - adc_P;
  p = (((p << 31) - var2) * 3125) / var1;
  var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
  var2 = (((int64_t)dig_P8) * p) >> 19;
  p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
  return (float)p / 256.0;
}

float calcAltitude(float pressure) {
  return 44330.0 * (1.0 - pow(pressure / SEA_LEVEL_HPA, 0.1903));
}

void setup() {
  Wire.begin();
  Serial.begin(9600);
  Serial.println("BMP280 Barometric Altimeter");
  Serial.println("--------------------------");

  uint8_t id = readReg(REG_ID);
  Serial.print("Chip ID: 0x");
  Serial.println(id, HEX);

  readCalibration();

  // Normal mode, temp x1, pressure x1
  writeReg(REG_CTRL_MEAS, 0x27);
  writeReg(REG_CONFIG, 0xA0);

  Serial.println("Ready. Drag sliders to change values.");
  Serial.println("--------------------------");
}

void loop() {
  float tempC   = readTemperature();
  float presHpa = readPressure() / 100.0;
  float altM    = calcAltitude(presHpa);

  Serial.print("Temp:      ");
  Serial.print(tempC, 1);
  Serial.println(" C");

  Serial.print("Pressure:  ");
  Serial.print(presHpa, 1);
  Serial.println(" hPa");

  Serial.print("Altitude:  ");
  Serial.print(altM, 1);
  Serial.println(" m");

  Serial.println("--------------------------");
  delay(2000);
}
